"• Tienes 30 días para cambiar de opinión; si inicias sesión antes de ese tiempo, la solicitud se cancelará automáticamente.":"• 30일 안에 마음이 바뀌면 요청을 취소할 수 있어요. 그 전에 로그인하면 요청이 자동으로 취소돼요.",
