"Tus beneficios Orbit están desactivados":"Orbit 혜택이 꺼져 있어요",
"Tu suscripción sigue pagada hasta el {fecha}, pero cancelaste la renovación: los beneficios Orbit están desactivados desde ahora.":"구독은 {fecha}까지 결제된 상태로 유지되지만 갱신을 취소했어요: Orbit 혜택은 지금부터 비활성화돼요.",
"Tu suscripción sigue pagada, pero cancelaste la renovación: los beneficios Orbit están desactivados desde ahora.":"구독은 아직 결제된 상태이지만 갱신을 취소했어요: 지금부터 Orbit 혜택이 비활성화돼요.",
"Tu suscripción sigue pagada hasta el {fecha}, pero cancelaste la renovación.":"구독은 {fecha}까지 결제되어 있지만 갱신을 취소했어요.",
"Tu suscripción sigue pagada, pero cancelaste la renovación.":"구독은 아직 결제된 상태이지만 갱신을 취소했어요.",
"Tu último pago falló: los beneficios Orbit están desactivados hasta que actualices tu método de pago.":"마지막 결제에 실패했어요: 결제 수단을 업데이트할 때까지 Orbit 혜택이 비활성화돼요.",
